// Generated by OrchestKit Claude Plugin
// Created: 2026-08-01

/**
 * Unit tests for multi-step-task-nudge (UserPromptSubmit sub-hook)
 *
 * Fixtures are REAL prompts from the 2026-08-01 session in which the operator
 * complained about coin-flip task usage — the session this hook exists to fix.
 * The load-bearing behaviours: precision-first detection (a miss costs
 * nothing, a false fire costs trust), permanent per-session silence once any
 * task exists, and a counter that keeps advancing even while silenced (it is
 * the Stop-side telemetry's denominator).
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookInput } from '../../types.js';
import {
  multiStepTaskNudge,
  isMultiStepShaped,
  qualifyingPromptCount,
  __internals,
} from '../../prompt/multi-step-task-nudge.js';
import { sessionHasTasks } from '../../lib/task-usage-signal.js';

let dir: string;
let projectDir: string;
let session = 0;

// CLAUDE_PLUGIN_DATA is the var getSessionStorageDir() actually honors — see
// the isolation note in visual-style-nudge.test.ts (counters written into the
// real session storage survive between runs and poison every rerun).
beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'task-nudge-'));
  projectDir = mkdtempSync(join(tmpdir(), 'task-nudge-proj-'));
  process.env.CLAUDE_PLUGIN_DATA = dir;
  session += 1;
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
  rmSync(projectDir, { recursive: true, force: true });
  delete process.env.CLAUDE_PLUGIN_DATA;
});

function prompt(text: string, sid = `s-${session}`): HookInput {
  return {
    tool_name: '',
    session_id: sid,
    prompt: text,
    project_dir: projectDir,
    tool_input: {},
  } as unknown as HookInput;
}

function fired(r: ReturnType<typeof multiStepTaskNudge>): boolean {
  const out = r.hookSpecificOutput as { additionalContext?: string } | undefined;
  return typeof out?.additionalContext === 'string' && out.additionalContext.length > 0;
}

function contextOf(r: ReturnType<typeof multiStepTaskNudge>): string {
  const hso = (r as { hookSpecificOutput?: { additionalContext?: string } }).hookSpecificOutput;
  return hso?.additionalContext ?? '';
}

/** Seed the project's task-creations log with an entry for `sid`. */
function seedTaskLog(sid: string): void {
  const logDir = join(projectDir, '.claude', 'logs');
  mkdirSync(logDir, { recursive: true });
  writeFileSync(
    join(logDir, 'task-creations.jsonl'),
    `${JSON.stringify({
      timestamp: '2026-08-01T08:00:00Z',
      event: 'task_created',
      task_id: '1',
      task_subject: 'Scout existing prompt-hook + task-state infrastructure',
      session_id: sid,
    })}\n`,
    'utf8',
  );
}

// ---------------------------------------------------------------------------
// Shape detection
// ---------------------------------------------------------------------------

describe('isMultiStepShaped', () => {
  it('detects a verb pile (real session prompt shape)', () => {
    expect(
      isMultiStepShaped(
        'Fix the docs counts, add a drift gate, then rebuild the plugins and verify CI passes',
      ),
    ).toBe(true);
  });

  it('detects a numbered plan', () => {
    expect(isMultiStepShaped('please do this:\n1. fix the gate\n2. rebuild\n3. open a PR')).toBe(
      true,
    );
  });

  it('detects two verbs joined by sequencing', () => {
    expect(isMultiStepShaped('migrate the config format and then update every consumer')).toBe(
      true,
    );
  });

  it('does not fire on a single-action request', () => {
    expect(isMultiStepShaped('please fix the flaky login test when you get a chance')).toBe(false);
  });

  it('MISS accepted: terse multi-step asks stay quiet (precision over recall)', () => {
    // Real prompt from the source session. It deserved a task list, but terse
    // prompts carry no detectable structure; firing on this shape would also
    // fire on one-liners constantly. The harness's own reminder still covers
    // these — this hook only claims the explicit-structure subset.
    expect(isMultiStepShaped('yes fix it and make sure wont happen again')).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// The hook: gating, silencing, throttle
// ---------------------------------------------------------------------------

const QUALIFYING =
  'Fix the docs counts, add a drift gate, then rebuild the plugins and verify CI passes';

describe('multiStepTaskNudge', () => {
  it('fires on qualifying work when the session has no tasks', () => {
    expect(fired(multiStepTaskNudge(prompt(QUALIFYING)))).toBe(true);
  });

  it('EXPLICIT: the operator complaint that motivated this hook always fires', () => {
    // Verbatim from the 2026-08-01 session (typo included). "todo" makes it
    // explicit — explicit asks bypass the throttle entirely.
    const complaint =
      'its really annoying that somestiems we use todo and sometimes we dont to organize oru session better...';
    expect(fired(multiStepTaskNudge(prompt(complaint)))).toBe(true);
    expect(fired(multiStepTaskNudge(prompt(complaint)))).toBe(true); // not throttled
  });

  it('stays quiet on short prompts', () => {
    expect(fired(multiStepTaskNudge(prompt('go')))).toBe(false);
  });

  it('stays quiet on skill-routed prompts — the route owns its own ceremony', () => {
    expect(
      fired(multiStepTaskNudge(prompt('what about all /ork:verify in fumadocs and about pages'))),
    ).toBe(false);
  });

  it('goes permanently silent once the session has a task', () => {
    const sid = `s-${session}`;
    seedTaskLog(sid);
    expect(fired(multiStepTaskNudge(prompt(QUALIFYING, sid)))).toBe(false);
  });

  it('#3733 cap: with no tasks all session, 1st fires, the 3rd fires the final line, silent after', () => {
    // The control that fails on main: main re-fires the 7th forever.
    const results = Array.from({ length: 7 }, () => fired(multiStepTaskNudge(prompt(QUALIFYING))));
    expect(results).toEqual([true, false, true, false, false, false, false]);
  });

  it('#3733 final line is conditional on TaskCreate and announces silence', () => {
    multiStepTaskNudge(prompt(QUALIFYING));
    multiStepTaskNudge(prompt(QUALIFYING));
    const third = contextOf(multiStepTaskNudge(prompt(QUALIFYING)));
    expect(third).toContain('[task-nudge #3 final]');
    expect(third).toContain('If TaskCreate is available');
    expect(third).toContain('stays silent for the rest of the session');
    expect(third).not.toContain('Open one now');
  });

  it('#3733 full nudge never asserts the tool exists', () => {
    const first = contextOf(multiStepTaskNudge(prompt(QUALIFYING)));
    expect(first).toContain("If TaskCreate is in this session's tool set");
    expect(first).not.toMatch(/Open one now —/);
  });

  it('#3733 explicit asks still fire past the cap, conditionally worded', () => {
    for (let i = 0; i < 4; i++) multiStepTaskNudge(prompt(QUALIFYING));
    const explicit = contextOf(multiStepTaskNudge(prompt('please organise the session with a todo list for this work')));
    expect(explicit).toContain('conditional]');
    expect(explicit).toContain('If TaskCreate is available');
  });

  it('#3733 a TaskCreated before the cap restores normal silencing, counter keeps advancing', () => {
    const sid = `s-${session}`;
    multiStepTaskNudge(prompt(QUALIFYING, sid));
    multiStepTaskNudge(prompt(QUALIFYING, sid));
    seedTaskLog(sid);
    expect(fired(multiStepTaskNudge(prompt(QUALIFYING, sid)))).toBe(false);
    expect(qualifyingPromptCount(sid)).toBe(3);
  });

  it('#3733 counter keeps advancing while capped', () => {
    const sid = `s-${session}`;
    for (let i = 0; i < 5; i++) multiStepTaskNudge(prompt(QUALIFYING, sid));
    expect(qualifyingPromptCount(sid)).toBe(5);
  });

  it('#3733 the cap clamps to at least 2 and the throttle is unchanged under a high cap', () => {
    expect(__internals.DOWNGRADE_AFTER).toBeGreaterThanOrEqual(2);
    expect(__internals.THROTTLE_EVERY).toBe(6);
  });

  it('counter advances even while silenced by existing tasks (telemetry denominator)', () => {
    const sid = `s-${session}`;
    seedTaskLog(sid);
    multiStepTaskNudge(prompt(QUALIFYING, sid));
    multiStepTaskNudge(prompt(QUALIFYING, sid));
    expect(qualifyingPromptCount(sid)).toBe(2);
  });
});

// ---------------------------------------------------------------------------
// The shared signal
// ---------------------------------------------------------------------------

describe('sessionHasTasks', () => {
  it('false when no log exists', () => {
    expect(sessionHasTasks(projectDir, 'nope')).toBe(false);
  });

  it('true when the tail carries this session', () => {
    seedTaskLog('sid-here');
    expect(sessionHasTasks(projectDir, 'sid-here')).toBe(true);
  });

  it('false when the log belongs to other sessions', () => {
    seedTaskLog('someone-else');
    expect(sessionHasTasks(projectDir, 'sid-here')).toBe(false);
  });

  it('fails CLOSED as true on unusable input — silence beats noise', () => {
    expect(sessionHasTasks('', 'sid')).toBe(true);
    expect(sessionHasTasks(projectDir, '')).toBe(true);
  });
});
